from flask import Flask, request, jsonify
import pickle

app = Flask(__name__)

@app.route('/pickle', methods=['POST'])
def load_pickle():
    '''
    Load pickle data from request
    '''
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        try:
            pickle_data = pickle.loads(file.read())
            return jsonify(pickle_data)
        except (pickle.UnpicklingError, EOFError) as e:
            return jsonify({'error': 'Invalid pickle data'}), 400
    else:
        return jsonify({'error': 'Allowed file types: pkl'}), 400

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() == 'pkl'
