import pickle
from datetime import datetime
from http.server import BaseHTTPRequestHandler, HTTPServer


class Todo:
    def __init__(self, task, due_date, completed=False):
        self.task = task
        self.due_date = due_date
        self.completed = completed

    def is_overdue(self):
        return datetime.now() > self.due_date


TODOS = {}


class TodoHandler(BaseHTTPRequestHandler):

    def load_todos(self):
        if self.path != '/load':
            return

        try:
            with open(self.path[1:], 'rb') as file:
                todos = pickle.load(file)
                for todo in todos.values():
                    TODOS[todo.task] = todo
                self.send_response(200)
                self.send_header('Content-type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'Todos loaded successfully.')
        except FileNotFoundError:
            self.send_error(404, 'File not found')
        except Exception as e:
            self.send_error(500, str(e))


    def do_GET(self):
        if self.path == '/load':
            self.load_todos()
        elif self.path.startswith('/'):
            task = self.path[1:]
            if task in TODOS:
                todo = TODOS[task]
                overdue_str = 'OVERDUE' if todo.is_overdue() else 'Not overdue'
                self.send_response(200)
                self.send_header('Content-type', 'text/html')
                self.end_headers()
                output = f"""
                <h1>Todo</h1>
                <b>Task:</b> {todo.task}<br>
                <b>Due Date:</b> {todo.due_date}<br>
                <b>Status:</b> {overdue_str}<br>
                """
                self.wfile.write(output.encode())
            else:
                self.send_error(404, 'Task not found')
        else:
            self.send_error(404, 'Invalid request')


server = HTTPServer(('', 80), TodoHandler)
server.serve_forever()
